namespace {using U=std::uint32_t;constexpr U sites[]={0x10003f00,0x100040c0,0x10003ed0,0x10003f80,0x10004090};constexpr U sizes[]={16,16,12,20,12};struct Test{std::array<U,24>row{};std::vector<std::uint8_t>data=std::vector<std::uint8_t>(0x100000),stack=std::vector<std::uint8_t>(0x100000);dfre::MissionNetsockPacketMemoryBindings foreign;std::unique_ptr<dfre::MissionNetsockPacketMemory>image;struct F{U site,at,n,id;};std::vector<F>frames;U serial=0,reads=0,writes=0,calls=0;std::uint64_t trace=0;Test(const dfre::AssetBytes&raw){foreign.read=[&](U a,U n){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;};foreign.write=[&](U a,U n,U v){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));};foreign.resolve=[&](U a,std::size_t n){return ptr(a,n);};image=std::make_unique<dfre::MissionNetsockPacketMemory>(raw,foreign);}std::uint8_t*ptr(U a,std::size_t n){if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=0x3000000&&std::uint64_t(a-0x3000000)+n<=stack.size())return stack.data()+a-0x3000000;throw std::runtime_error("Admission fixture address is not mapped");}U get(U a,U n=4){return image->read(a,n);}void put(U a,U v,U n=4){image->write(a,n,v);}U norm(U a){for(auto i=frames.rbegin();i!=frames.rend();++i)if(a>=i->at&&a<i->at+i->n)return 0x30000000+i->id*0x1000+a-i->at;return a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}bool mapped(U a,U n){if(a>=0x10000000&&std::uint64_t(a)+n<=0x1001b000)return true;if(a>=0x1200000&&std::uint64_t(a)+n<=0x1300000)return true;for(auto f:frames)if(a>=f.at&&std::uint64_t(a)+n<=std::uint64_t(f.at)+f.n)return true;return false;}U frame(U s){for(auto i=frames.rbegin();i!=frames.rend();++i)if(i->site==s)return i->at;return 0;}U make(U s,U n,const std::vector<U>&args){const U a=0x3000000+serial*0x400;frames.push_back({s,a,n,serial++});std::fill_n(ptr(a,n),n,0x5a);U off=4;for(U v:args){put(a+off,v);off+=4;}return a;}U input(){return row[8]?0x1220000:0x1200000;}
void setup(){serial=reads=writes=calls=0;trace=1469598103934665603ull;frames.clear();std::fill(data.begin(),data.end(),0x5a);std::fill_n(image->resolve(0x10019880,0x426),0x426,0);for(auto[a,v]:std::vector<std::pair<U,U>>{{0x100198b0,0x100},{0x100198b4,row[2]?8u:0u},{0x100198b8,row[4]},{0x10019c5c,0x1220000},{0x10019af8,0x1240000},{0x10019b00,row[6]?0x1260000u:0u},{0x12600a0,row[17]}})put(a,v);put(0x10019868,0x4321,2);for(U i=0;i<row[19];++i){put(0x10019940+i,'a'+i%26,1);put(input()+0x14+i,'a'+i%26,1);}put(0x10019940+row[19],0,1);put(input()+0x14+row[19],0,1);if(!row[3])put(input()+0x14,'z',1);if(row[3]==2)put(input()+0x15,'z',1);for(U j=0;j<4;++j){const U key=0x11111111u*(j+1);put(0x10019990+j*4,key);put(input()+4+j*4,key+((!row[1]&&j==0)||(row[1]==2&&j==3)?1:0));}put(input(),row[20],2);put(input()+2,0x54,2);std::fill_n(ptr(0x1240000,0x8000),0x8000,0);for(U i=0;i<row[4];++i){const U a=0x1240000+i*0x18;const bool active=row[5]==3||((row[5]==1||row[5]==2)&&i==0)||(row[5]==4&&i==1);put(a,active);put(a+4,(row[5]==3?row[15]+1+i:row[15]));put(a+0xc,row[5]==2?1:0);put(a+0x14,row[16]);}}
dfre::MissionNetsockAdmissionBindings bindings(){dfre::MissionNetsockAdmissionBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[12]||!mapped(a,n))throw std::runtime_error("Read failure");if((row[11]&1)&&a==0x10019990)put(input()+4,0xdeadbeef);if((row[11]&2)&&a==input()+4)put(0x10019990,0xdeadbeef);if((row[11]&32)&&frame(0x10003f80)&&a==frame(0x10003f80)+0x10)put(frame(0x10003f80)+0xc,0x0300007f);if((row[11]&64)&&a==0x10019b00)put(0x12600a0,0x20000);if((row[11]&128)&&a==0x12600a0)put(0x10019b00,0);if((row[11]&1024)&&a==input()+0x14)put(0x10019940,'z',1);if((row[11]&2048)&&a==0x10019940)put(input()+0x14,'z',1);if((row[11]&4096)&&a==0x100198b4&&frame(0x100040c0)){put(frame(0x100040c0)+8,0x0400007f);put(frame(0x100040c0)+12,0xabcdef01);}return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(n==4?v:v&((1u<<(8*n))-1)));if(++writes==row[13]||!mapped(a,n))throw std::runtime_error("Store failure");if((row[11]&16)&&(a==0x1220004||a==0x1224004)){put(0x10019c5c,0x1224000);put(a-2,0x108,2);}put(a,v,n);};b.before_call=[&](U s,const auto&args){event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[14])throw std::runtime_error("Call failure");if((row[11]&4)&&s==0x10003ed0){put(0x10019c5c,0x1224000);if(frame(0x10003f00)){put(frame(0x10003f00)+8,0x0500007f);put(frame(0x10003f00)+12,0x99998888);}}if((row[11]&8)&&s==0x10004090&&frame(0x100040c0)){put(frame(0x100040c0)+8,0x0600007f);put(frame(0x100040c0)+12,0x77776666);}if((row[11]&256)&&s==0x10003fe0&&frame(0x10004090)){put(frame(0x10004090)+4,0x0700007f);put(frame(0x10004090)+8,0x55554444);}if(s==0x10004600)throw std::runtime_error("Required active-address removal fixture");};b.call=[&](U s,const auto&)->U{if(s==0x10005020)return row[7];throw std::runtime_error("Admission required service is not bound");};b.frame=[&](U s,U n,const auto&args){return make(s,n,args);};b.release=[&](U,U,U){frames.pop_back();};b.resolve=[&](U a,std::size_t n){return image->resolve(a,n);};return b;}
};}
int main(int argc,char**argv){if(argc!=2)return 1;std::ifstream file(argv[1],std::ios::binary);dfre::AssetBytes raw((std::istreambuf_iterator<char>(file)),{});Test t(raw);std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();auto b=t.bindings();U op=t.row[0];std::vector<U>args=op==0||op==1?std::vector<U>{t.input(),t.row[15],t.row[16]}:op==3?std::vector<U>{t.row[9],t.row[10],t.row[15],t.row[16]}:std::vector<U>{t.row[15],t.row[16]};const U f=t.make(sites[op],sizes[op],args);bool failed=false;U result=0;try{result=dfre::mission_netsock_admission_call(b,sites[op],f);}catch(const std::runtime_error&){failed=true;}if(t.frames.size()!=1)return 3;if(failed||op!=4)result=0;std::uint64_t state=1469598103934665603ull;for(auto[a,n]:std::vector<std::pair<U,U>>{{0x10019880,0x426},{0x1200000,0x1000},{0x1220000,0x8000},{0x1240000,0x8000},{0x1260000,0x1000}}){const auto*p=t.image->resolve(a,n);for(U i=0;i<n;++i){state^=p[i];state*=1099511628211ull;}}std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
